def check_subset_small_case():
    # Let S have 2 distinct elements, S = {s1, s2}. Let d = s1 - s2 (d != 0).
    # P1 = {0, d, -d}
    P1 = {0.0, 1.0, -1.0} # Using d=1 for concrete numbers

    # Calculate P2 = {3*p*q*r | p, q in P1}
    P2 = set()
    for p in P1:
        for q in P1:
            for r in P1:
                P2.add(3 * p * q * r)

    # Calculate P3 = {x^2 + y^2 - z^2 - w^2 | x, y, z, w in P1}
    # P1_sq = {x^2 | x in P1} = {0^2, 1^2, (-1)^2} = {0, 1}
    P1_sq = {x**2 for x in P1}

    P3 = set()
    for x2 in P1_sq:
        for y2 in P1_sq:
            for z2 in P1_sq:
                for w2 in P1_sq:
                    P3.add(x2 + y2 - z2 - w2)

    print(f"P1: {P1}")
    print(f"P2 calculated: {sorted(list(P2))}")
    print(f"P3 calculated: {sorted(list(P3))}")

    # Check containment
    P2_is_subset_of_P3 = P2.issubset(P3)
    print(f"Is P2 a subset of P3? {P2_is_subset_of_P3}")

